 select 'S101-ROOM',b.id,r.id,a.id,b.travel_date,6,1,r.buy_cents,r.sell_cents,'requested',current_date-2,current_date+1,null from tours.bookings b,tours.rates r,tours.allotments a where b.code='NZ101' and r.code='ROOM-SUM' and a.code='LAKE-01' and not exists(select 1 from tours.services where code='S101-ROOM') on conflict do nothing;
 select x.code,b.id,r.id,b.travel_date,x.units,1,r.buy_cents,r.sell_cents,x.status,current_date-1,current_date+2,x.ref from (values ('S101-BUS','NZ101','BUS-SUM',1,'confirmed','DEMO-COACH-1'),('S101-RAFT','NZ101','RAFT-SUM',12,'requested',null),('S103-ROOM','NZ103','ROOM-SUM',4,'confirmed','DEMO-ROOM-2')) x(code,booking,rate,units,status,ref) join tours.bookings b on b.code=x.booking join tours.rates r on r.code=x.rate where not exists(select 1 from tours.services where code=x.code) on conflict do nothing;
