insert into tours.suppliers(code,name,email) values ('LAKE','Lakeview Lodge','reservations@example.invalid'),('COACH','Southern Coaches','dispatch@example.invalid') on conflict do nothing;
insert into tours.suppliers(code,name,email,adventure_activity,registration_ref,registration_until,registration_checked_on) values ('RIVER','River Valley Adventures','ops@example.invalid',true,'DEMO-NOT-A-REAL-REGISTRATION',current_date-1,current_date-30) on conflict do nothing;
insert into tours.products(code,supplier_id,name,kind,location) select x.code,v.id,x.name,x.kind,x.location from (values ('ROOM','LAKE','Lakeview twin room','accommodation','Queenstown'),('BUS','COACH','Airport group transfer','transport','Queenstown'),('RAFT','RIVER','River rafting','activity','Queenstown')) x(code,supplier,name,kind,location) join tours.suppliers v on v.code=x.supplier on conflict do nothing;
insert into tours.rates(code,product_id,valid_from,valid_to,currency,unit,buy_cents,sell_cents,release_days,cancellation_terms) select x.code,p.id,current_date-60,current_date+120,'NZD',x.unit,x.buy,x.sell,14,'Demo contract: check cancellation date before confirming.' from (values ('ROOM-SUM','ROOM','room',24000,30000),('BUS-SUM','BUS','vehicle',80000,105000),('RAFT-SUM','RAFT','person',18000,19500)) x(code,product,unit,buy,sell) join tours.products p on p.code=x.product on conflict do nothing;
